BuildContext context;
List<Widget> houseNumbers = [];

void getHouseNumbers() async {
  final database = await openDatabase(
    'house_numbers.db',
    version: 1,
    onCreate: (db, _) {
      db.execute(
          'CREATE TABLE HouseNumbers (id INTEGER PRIMARY KEY, number INTEGER)');
    },
  );

  // Insert data into the table
  await database.execute(
      'INSERT INTO HouseNumbers (number) VALUES (?), (?), (?), (?), (?)',
      [1, 2, 3, 4, 5]);

